function switchTab(btn, cluster){
  const section = btn.closest('.cluster-section');
  section.querySelectorAll('.sub-tab').forEach(b=>b.classList.remove('active'));
  section.querySelectorAll('.tower-panel').forEach(p=>p.classList.remove('active'));
  btn.classList.add('active');
  section.querySelector('[data-panel="'+btn.dataset.target+'"]').classList.add('active');
}

function csvEscape(v){ return '"'+String(v).replace(/"/g,'""')+'"'; }

function buildCSV(towers){
  let rows = [["Tower","Unit No.","Floor","Configuration","Chargeable Area (sqft)","Plot Area (sqft)","Price (AED)","View","Parking Slots"]];
  towers.forEach(t=>{
    t.configs.forEach(c=>{
      c.units.forEach(u=>{
        rows.push([t.tower, u.unit, u.floor, c.config, u.area, u.plot||"-", u.price, u.view||"-", u.park||"-"]);
      });
    });
    t.commercial.forEach(u=>{
      rows.push([t.tower, u.unit, "-", u.type, u.area, "-", u.price, u.view||"-", u.park||"-"]);
    });
  });
  return rows.map(r=>r.map(csvEscape).join(",")).join("\n");
}

function triggerDownload(filename, content){
  const blob = new Blob([content], {type:'text/csv;charset=utf-8;'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

function downloadClusterCostSheet(clusterKey){
  const towers = CLUSTER_DATA[clusterKey];
  const csv = buildCSV(towers);
  triggerDownload('SobhaHartlandII-'+clusterKey+'-CostSheet.csv', csv);
}

function downloadTowerCostSheet(clusterKey, towerSlug){
  const match = CLUSTER_DATA[clusterKey].filter(t=>{
    const s = t.tower.toLowerCase().replace(/\s+/g,'-').replace(/[()]/g,'');
    return s === towerSlug;
  });
  const csv = buildCSV(match.length?match:CLUSTER_DATA[clusterKey]);
  triggerDownload('SobhaHartlandII-'+towerSlug+'-CostSheet.csv', csv);
}

window.addEventListener('scroll', ()=>{
  const h = document.querySelector('.site-header');
  if(window.scrollY>10) h.style.boxShadow='0 4px 20px rgba(0,0,0,.06)'; else h.style.boxShadow='none';
});

/* ---- Gentle auto-scroll for the single waterfront gallery ---- */
(function () {
  var gallery = document.querySelector('[data-autoslide="true"]');
  if (!gallery) return;
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  var track = gallery.querySelector('[data-track]');
  if (!track) return;
  var paused = false, resumeTimer = null;
  function advance(){
    if (paused) return;
    var slide = track.querySelector('.ag-slide');
    if (!slide) return;
    var slideWidth = slide.getBoundingClientRect().width + 14;
    var maxScroll = track.scrollWidth - track.clientWidth;
    if (track.scrollLeft + slideWidth > maxScroll - 4) track.scrollTo({left:0, behavior:'smooth'});
    else track.scrollBy({left:slideWidth, behavior:'smooth'});
  }
  function pause(ms){ paused = true; clearTimeout(resumeTimer); resumeTimer = setTimeout(function(){paused=false;}, ms||7000); }
  track.addEventListener('touchstart', function(){pause(8000);}, {passive:true});
  track.addEventListener('mousedown', function(){pause(8000);});
  track.addEventListener('wheel', function(){pause(4000);}, {passive:true});
  var inView = false;
  if ('IntersectionObserver' in window){
    var io = new IntersectionObserver(function(entries){ entries.forEach(function(e){ inView = e.isIntersecting; }); }, {threshold:0.3});
    io.observe(gallery);
  } else inView = true;
  setInterval(function(){ if (inView && !paused && document.visibilityState==='visible') advance(); }, 4500);
})();

/* ---- Privacy Modal ---- */
(function(){
  var pm = document.getElementById('privacyModal');
  if (!pm) return;
  var openLinks = document.querySelectorAll('[data-open-privacy]');
  var closeBtn = pm.querySelector('[data-close-privacy]');
  function open(){ pm.classList.add('open'); pm.setAttribute('aria-hidden','false'); document.body.style.overflow='hidden'; }
  function close(){ pm.classList.remove('open'); pm.setAttribute('aria-hidden','true'); document.body.style.overflow=''; }
  openLinks.forEach(function(l){ l.addEventListener('click', function(e){ e.preventDefault(); open(); }); });
  if (closeBtn) closeBtn.addEventListener('click', close);
  pm.addEventListener('click', function(e){ if (e.target===pm) close(); });
  document.addEventListener('keydown', function(e){ if (e.key==='Escape') close(); });
})();
